Section CANSEC1. Context {rc : runConstT}.

Lemma sqs_i5_ok : forall P OEND LLO LEND LOCV, sqs_static P OEND LLO LEND LOCV -> zd_initfse_stmtA ->
  (v_LLT P + 4104 < 2^47 /\ v_OFT P + 2056 < 2^47 /\ v_MLT P + 4104 < 2^47) ->
  ai_I7 P OEND LLO LEND LOCV -> ai_I5 P OEND LLO LEND LOCV.
Proof.
  intros P OEND LLO LEND LOCV ST IFS TST CONT.
  destruct P as [ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m SPV lo DCTX DST CAP B0 B1 SEQ nbSeq LLT MLT OFT PFX LITP LBE LITB LOC sq tLL tOF tML huf r0 r1 r2 pde dend expd pcs dsz bt stg le fe ws AI fflag L RNG st LB m0 FRB FF SHF D8 j0 j224 jfh j144 jsh0 jsh1].
  cbv delta [ai_I5 sqs_iregs sqs_ifrN sqs_ifrI sqs_imidC sqs_iffD]. cbn [app v_ra v_gp v_tp v_s0 v_s1 v_s2 v_s3 v_s4 v_s5 v_s6 v_s7 v_s8 v_s9 v_s10 v_s11 v_F v_fc v_m v_SPV v_lo v_DCTX v_DST v_CAP v_B0 v_B1 v_SEQ v_nbSeq v_LLT v_MLT v_OFT v_PFX v_LITP v_LBE v_LITB v_LOC v_sq v_tLL v_tOF v_tML v_huf v_r0 v_r1 v_r2 v_pde v_dend v_expd v_pcs v_dsz v_bt v_stg v_le v_fe v_ws v_AI v_fflag v_L v_RNG v_st v_LB v_m0 v_FRB v_FF v_SHF v_D8 v_j0 v_j224 v_jfh v_j144 v_jsh0 v_jsh1].
  intros m1 ja j128 j152 j176 jd jseq jpad j104 p0 p1 p2 cw A0 bc ptr sLL sOF x5 x6 x7 x13 x14 x15 x16 x17 x25 x28 x29 x30 x31 INV EA0 HBC BOK HS1 HS2.
  subst A0.
  cbv delta [ai_I7 sqs_iregs sqs_ifrN sqs_ifrI sqs_imidC sqs_ffr] in CONT. cbn [app v_ra v_gp v_tp v_s0 v_s1 v_s2 v_s3 v_s4 v_s5 v_s6 v_s7 v_s8 v_s9 v_s10 v_s11 v_F v_fc v_m v_SPV v_lo v_DCTX v_DST v_CAP v_B0 v_B1 v_SEQ v_nbSeq v_LLT v_MLT v_OFT v_PFX v_LITP v_LBE v_LITB v_LOC v_sq v_tLL v_tOF v_tML v_huf v_r0 v_r1 v_r2 v_pde v_dend v_expd v_pcs v_dsz v_bt v_stg v_le v_fe v_ws v_AI v_fflag v_L v_RNG v_st v_LB v_m0 v_FRB v_FF v_SHF v_D8 v_j0 v_j224 v_jfh v_j144 v_jsh0 v_jsh1] in CONT.
  (* [comment removed for export] *)
  pose proof INV as (FR0 & FRF0 & IREST).
  destruct (sqs_cb16_words m1 FF [CB 32 jfh; C8 cw; C4 (Z_to_bv 64 bc); CB 4 jpad; C8 (Z_to_bv 64 ptr); C8 (Z_to_bv 64 SEQ); C8 (Z_to_bv 64 (SEQ + 8)); C8 (Z_to_bv 64 sLL); C8 (Z_to_bv 64 (LLT + 8)); C8 (Z_to_bv 64 sOF); C8 (Z_to_bv 64 (OFT + 8))] j104 [C8 p0; C8 p1; C8 p2; CB 104 j144; C8 (Z_to_bv 64 (fflag L 2 FF))] FRF0) as (u1 & u2 & FRF1).
  cbn [app] in FRF1.
  assert (INV1 : sqs_iinv (mkSSQ ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m SPV lo DCTX DST CAP B0 B1 SEQ nbSeq LLT MLT OFT PFX LITP LBE LITB LOC sq tLL tOF tML huf r0 r1 r2 pde dend expd pcs dsz bt stg le fe ws AI fflag L RNG st LB m0 FRB FF SHF D8 j0 j224 jfh j144 jsh0 jsh1) OEND LLO LEND LOCV m1 _ _) by (exact (conj FR0 (conj FRF1 IREST))).
  clear INV FR0 FRF0 FRF1 IREST.
  (* [comment removed for export] *)
  eapply evtF_cut.
  { eapply (sqs_initfse_ispec (mkSSQ ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m SPV lo DCTX DST CAP B0 B1 SEQ nbSeq LLT MLT OFT PFX LITP LBE LITB LOC sq tLL tOF tML huf r0 r1 r2 pde dend expd pcs dsz bt stg le fe ws AI fflag L RNG st LB m0 FRB FF SHF D8 j0 j224 jfh j144 jsh0 jsh1) OEND LLO LEND LOCV m1 _ cw bc jpad ptr [C8 (Z_to_bv 64 sLL); C8 (Z_to_bv 64 (LLT + 8)); C8 (Z_to_bv 64 sOF); C8 (Z_to_bv 64 (OFT + 8))] u1 u2 [C8 p0; C8 p1; C8 p2; CB 104 j144; C8 (Z_to_bv 64 (fflag L 2 FF))] MLT tML K_ML 82 (FF + 104) (DCTX + 26692) (2147450880 + D8 + 3336));
      [ exact ST | exact IFS | exact INV1 | cbn [v_LLT v_OFT v_MLT v_tLL v_tOF v_tML]; right; right; split; [reflexivity | split; reflexivity] | exact TST
      | cbn [cells_size csize Nat.add length v_FF]; clear; lia | cbn [cells_size csize Nat.add length]; clear; lia | cbn [cells_size csize Nat.add length]; clear; lia
      | clear - HBC; lia | clear; lia | exact BOK ]. }
  clear INV1. cbv delta [sqs_initfse_ipost sqs_iregs]. cbn [v_ra v_gp v_tp v_s0 v_s1 v_s2 v_s3 v_s4 v_s5 v_s6 v_s7 v_s8 v_s9 v_s10 v_s11 v_F v_fc v_m v_SPV v_lo v_DCTX v_DST v_CAP v_B0 v_B1 v_SEQ v_nbSeq v_LLT v_MLT v_OFT v_PFX v_LITP v_LBE v_LITB v_LOC v_sq v_tLL v_tOF v_tML v_huf v_r0 v_r1 v_r2 v_pde v_dend v_expd v_pcs v_dsz v_bt v_stg v_le v_fe v_ws v_AI v_fflag v_L v_RNG v_st v_LB v_m0 v_FRB v_FF v_SHF v_D8 v_j0 v_j224 v_jfh v_j144 v_jsh0 v_jsh1].
  intros ms2 (m2 & cw2 & bc2 & jpad2 & ptr2 & sv & t0_ & t1_ & t2_ & a0_ & a1_ & a2_ & a3_ & a4_ & a5_ & a6_ & a7_ & t3_ & t4_ & t5_ & t6_ & -> & INV2 & HST & HBC2 & BOK2).
  replace (ret_pc (Z_to_bv 64 591536)) with (Z_to_bv 64 591536) by (symmetry; apply ret_pc_even; [ lia | reflexivity ]).
  cbv delta [sbd_cells] in INV2. cbn [app] in INV2.
  (* [comment removed for export] *)
  eapply CONT; [exact INV2 | clear - HBC2; lia | exact BOK2 | exact HS1 | exact HS2 | exact HST].
Qed.

End CANSEC1.
